'use strict';
const app=document.querySelector('#app');
const svg=(content,cls='')=>`<svg class="${cls}" viewBox="0 0 320 320" aria-hidden="true">${content}</svg>`;
const arts={
 chick:()=>svg('<g fill="#ffe600"><path d="M119 68Q119 33 144 29Q164 25 156 50Q188 34 193 50Q200 64 181 72Z"/><ellipse cx="160" cy="169" rx="105" ry="107"/><path d="M68 157Q22 174 33 205Q46 228 76 199ZM252 157Q298 174 287 205Q274 228 244 199Z"/></g><g fill="#ff9b00"><path d="M111 266Q91 279 99 288Q105 293 117 286Q121 306 130 298Q134 292 130 280Q148 294 153 282Q155 271 131 265ZM189 266Q166 271 169 282Q174 294 191 280Q187 292 191 298Q200 306 204 286Q216 293 222 288Q230 279 210 266Z"/><path d="M145 153Q160 150 175 153Q184 154 179 164L166 181Q160 187 154 181L141 164Q136 154 145 153"/></g><g fill="#050505"><circle cx="121" cy="148" r="10"/><circle cx="199" cy="148" r="10"/></g>','chick-art'),
 car:()=>svg('<path fill="#0985ff" d="M49 150L76 93Q84 76 106 76H195Q213 76 227 96L257 146Q284 151 287 176V222H34V177Q34 155 49 150Z"/><path fill="#8edbff" d="M91 98H144V145H71ZM159 98H192Q201 98 207 109L229 145H159Z"/><path fill="#0985ff" d="M35 174H288V231H35Z"/><g fill="#282828"><circle cx="94" cy="230" r="38"/><circle cx="234" cy="230" r="38"/></g><g fill="#bdbdbd"><circle cx="94" cy="230" r="16"/><circle cx="234" cy="230" r="16"/></g>','car-art'),
 apple:()=>svg('<path fill="#87512e" d="M154 94Q145 65 164 39L178 46Q163 69 169 95Z"/><path fill="#6dde22" d="M172 73Q197 22 245 49Q227 89 172 73Z"/><path fill="#ff293a" d="M160 100Q105 70 71 112Q36 152 71 229Q104 300 160 268Q216 300 249 229Q284 152 249 112Q215 70 160 100Z"/>','apple-art'),
 star:()=>svg('<path fill="#ffe600" stroke="#ffe600" stroke-linejoin="round" stroke-width="14" d="M160 43L195 115L276 127L217 184L231 266L160 228L89 266L103 184L44 127L125 115Z"/>','star-art'),
 circle:()=>svg('<circle cx="160" cy="160" r="111" fill="#ffe600"/>'),
 horse:()=>svg('<path fill="#00dce9" d="M48 137L76 100L83 56L103 91L136 116L155 149H235L269 171L275 222L301 251L274 241L254 210L239 221L247 286H221L208 223H159L141 286H116L128 204L106 147L76 165Z"/>'),
 cup:()=>svg('<path d="M224 118H255Q294 119 278 163Q265 196 228 192" fill="none" stroke="#ff293a" stroke-width="23"/><path fill="#ff293a" d="M58 89H240L231 210Q224 260 151 260Q78 260 70 210Z"/>')
};
const levels=[{id:'chick',name:'让小鸡跳舞',target:'小鸡',action:'和小鸡打招呼',feedback:'小鸡跳起舞啦！'}, {id:'car',name:'让小车开起来',target:'小车',action:'让小车出发',feedback:'小车出发啦！'}, {id:'apple',name:'摘下红苹果',target:'红苹果',action:'摘下红苹果',feedback:'摘到苹果啦！'}, {id:'star',name:'点亮小星星',target:'小星星',action:'点亮小星星',feedback:'小星星亮起来啦！'}];
const phases=[{id:1,art:'circle',name:'发现目标'},{id:2,art:'horse',name:'认识物品'},{id:3,art:'cup',name:'生活探索'}];
const modes=[{id:'slap',name:'拍击',description:'触碰屏幕任意位置即可回应'},{id:'precise',name:'精准点击',description:'点击目标物体，触碰其他位置不会触发'},{id:'dwell',name:'悬停',description:'接触目标并停留 1.2 秒，无需抬手'}];
const S={page:'home',phase:1,level:0,mode:'slap',round:0,overlay:null,reward:0,hold:null,toast:'',toastRemaining:0,targetSlot:0};
let audio=null,soundOn=false,lastTick=0;
const icon={pause:'<svg viewBox="0 0 24 24"><path d="M7 4v16M17 4v16" stroke="currentColor" stroke-width="4" stroke-linecap="round"/></svg>',menu:'<svg viewBox="0 0 24 24"><path d="M3 5h18M3 12h18M3 19h18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>',back:'<svg viewBox="0 0 24 24"><path d="m15 4-8 8 8 8" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>'};
function sound(){if(!soundOn)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const t=audio.currentTime;[523.25,659.25,783.99].forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(0,t+i*.11);g.gain.linearRampToValueAtTime(.04,t+i*.11+.015);g.gain.exponentialRampToValueAtTime(.001,t+i*.11+.2);o.start(t+i*.11);o.stop(t+i*.11+.22);});}catch{}}
function endHold(){S.hold=null;document.querySelector('.dwell-ring')?.remove();}
function setOverlay(value){endHold();S.overlay=value;render();}
function startLevel(index=S.level){endHold();S.page='game';S.level=index;S.round=0;S.reward=0;S.overlay=null;S.targetSlot=0;S.toast='';render();}
function tell(message){S.toast=message;S.toastRemaining=1800;const n=document.querySelector('.toast');if(n)n.textContent=message;}
function home(){endHold();Object.assign(S,{page:'home',overlay:null,reward:0});render();}
function phaseView(){endHold();Object.assign(S,{page:'phases',overlay:null,reward:0});render();}
function homeView(){return `<section class="page home" aria-label="开始游戏"><button class="home-chick" data-action="start" aria-label="点击或拍击来开始">${arts.chick()}</button><h1 class="home-prompt">点击或拍击来开始吧！</h1><span class="quiet-brand">微动星瞳 · 游戏 DEMO</span></section>`;}
function phasesView(){return `<section class="page"><div class="topbar"><button class="icon-btn" data-action="home" aria-label="返回首页">${icon.back}</button><span class="top-spacer"></span><button class="small-btn" data-action="fullscreen">全屏体验</button></div><h1 class="phase-heading">选择探索模式</h1><div class="phase-grid">${phases.map(p=>`<button class="phase-card" data-phase="${p.id}" aria-label="Phase ${['','I','II','III'][p.id]} ${p.name}"><div class="art">${arts[p.art]()}</div><strong>Phase ${['','I','II','III'][p.id]}</strong><span>${p.name}</span></button>`).join('')}</div><span class="quiet-brand">微动星瞳 · 横屏体验更舒展</span></section>`;}
function gameView(){const l=levels[S.level],count=S.phase===1?1:S.phase===2?2:3;const other=levels.filter(x=>x.id!==l.id);const items=Array.from({length:count},(_,i)=>i===S.targetSlot?{...l,isTarget:true}:{...other[(i+S.round)%other.length],isTarget:false});return `<section class="page game phase${S.phase}"><div class="topbar"><button class="icon-btn" data-action="pause" aria-label="暂停游戏">${icon.pause}</button><button class="icon-btn" data-action="menu" aria-label="打开游戏菜单">${icon.menu}</button></div><h1 class="game-title">${l.name}</h1><div class="rounds" aria-label="已完成 ${S.round} 次，共 3 次">${[0,1,2].map(i=>`<i class="${i<S.round?'done':''}"></i>`).join('')}</div><div class="playfield ${count===1?'single':''}">${items.map(x=>`<button class="object ${x.isTarget?'target':'distractor'} ${x.isTarget&&S.reward?'celebrate':''}" data-object="${x.isTarget?'target':'other'}" aria-label="${x.target}"><div class="art">${arts[x.id]()}</div></button>`).join('')}</div><p class="task-caption ${S.reward?'feedback':''}" aria-live="polite">${S.reward?l.feedback:instruction()}</p><p class="mode-note">${S.mode==='slap'?'拍击模式 · 点击或拍击屏幕即可回应':S.mode==='precise'?'精准点击 · 找到并点击'+l.target:'接触停留 · 按住'+l.target+' 1.2 秒'}</p><div class="toast" role="status">${S.toast}</div></section>`;}
function instruction(){const l=levels[S.level];if(S.mode==='slap')return `拍击屏幕，${l.action}`;if(S.mode==='precise')return `找到${l.target}，点一下吧！`;return `接触${l.target}并停留一会儿`}
function menuView(){return `<div class="overlay"><section class="drawer" role="dialog" aria-modal="true" aria-label="游戏菜单"><div class="drawer-head"><div><h2>游戏菜单</h2><p>游戏已暂停</p></div><button class="close-btn" data-action="resume" aria-label="关闭菜单">×</button></div><div class="section-head"><h3>选择关卡</h3><button class="phase-link" data-action="phases">Phase ${['','I','II','III'][S.phase]} · 切换阶段</button></div><div class="preview-grid">${levels.map((l,i)=>`<button class="preview ${S.level===i?'selected':''}" data-level="${i}" aria-pressed="${S.level===i}"><div class="preview-art">${arts[l.id]()}</div><span class="preview-label">${l.name}</span>${S.level===i?'<span class="selected-mark">✓</span>':''}</button>`).join('')}</div><h3 class="mode-head">交互模式</h3><div class="mode-row">${modes.map(m=>`<button class="mode-chip ${m.id===S.mode?'selected':''}" data-mode="${m.id}" aria-pressed="${m.id===S.mode}">${m.name}</button>`).join('')}</div><p class="mode-description">${modes.find(m=>m.id===S.mode).description}</p><button class="primary" data-action="resume">继续游戏</button></section></div>`;}
function pauseView(){return `<div class="overlay modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="游戏已暂停"><div class="pause-symbol">Ⅱ</div><h2>休息一下吧</h2><p>游戏已暂停，准备好再继续。</p><button class="primary" data-action="resume">继续游戏</button><button class="secondary" data-action="menu">选择关卡</button><button class="small-btn" data-action="home">返回首页</button><button class="small-btn" data-action="sound">${soundOn?'关闭':'开启'}声音反馈</button></section></div>`;}
function doneView(){return `<div class="overlay modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="关卡完成"><div class="modal-art">${arts[levels[S.level].id]()}</div><h2>这一关完成啦！</h2><p>完成了三次回应，继续探索吧。</p><button class="primary" data-action="next">${S.level===levels.length-1?'回到关卡选择':'试试下一关'}</button><button class="secondary" data-action="replay">再玩一次</button><button class="small-btn" data-action="menu">选择其他关卡</button></section></div>`;}
function render(){app.innerHTML=(S.page==='home'?homeView():S.page==='phases'?phasesView():gameView())+(S.overlay==='menu'?menuView():S.overlay==='pause'?pauseView():S.overlay==='done'?doneView():'');if(S.overlay){requestAnimationFrame(()=>document.querySelector('[role="dialog"] button')?.focus({preventScroll:true}));}}
function respond(){if(S.page!=='game'||S.overlay||S.reward)return;endHold();S.reward=1500;S.round++;S.toast='';sound();render();}
function action(name){switch(name){case'start':phaseView();break;case'home':home();break;case'phases':phaseView();break;case'pause':setOverlay('pause');break;case'menu':setOverlay('menu');break;case'resume':setOverlay(null);break;case'replay':startLevel();break;case'next':S.level===levels.length-1?setOverlay('menu'):startLevel(S.level+1);break;case'sound':soundOn=!soundOn;render();break;case'fullscreen':if(document.fullscreenElement){document.exitFullscreen?.().catch(()=>{});}else{document.documentElement.requestFullscreen?.().catch(()=>{});}break;}}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.action){action(b.dataset.action);return;}if(b?.dataset.phase){S.phase=Number(b.dataset.phase);startLevel(0);return;}if(b?.dataset.level!==undefined){endHold();S.level=Number(b.dataset.level);S.round=0;S.reward=0;S.targetSlot=0;render();return;}if(b?.dataset.mode){endHold();S.mode=b.dataset.mode;S.reward=0;S.round=0;S.targetSlot=0;render();return;}if(S.page==='home'){phaseView();return;}if(e.detail===0&&b?.dataset.object&&S.page==='game'&&!S.overlay){if(S.mode==='slap'||b.dataset.object==='target')respond();}});
app.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('[data-action],.overlay,[data-phase]'))return;if(S.page!=='game'||S.overlay||S.reward)return;const obj=e.target.closest('[data-object]');if(S.mode==='slap'){respond();return;}if(obj?.dataset.object!=='target'){if(obj)tell('再找找目标吧');return;}if(S.mode==='precise'){respond();return;}endHold();S.hold={id:e.pointerId,elapsed:0,node:obj};obj.insertAdjacentHTML('beforeend','<span class="dwell-ring"></span>');e.preventDefault();});
window.addEventListener('pointermove',e=>{if(!S.hold||e.pointerId!==S.hold.id)return;const r=S.hold.node.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)endHold();});
window.addEventListener('pointerup',e=>{if(S.hold?.id===e.pointerId)endHold();});window.addEventListener('pointercancel',endHold);window.addEventListener('blur',()=>{if(S.page==='game'&&!S.overlay)setOverlay('pause');else endHold();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&S.page==='game'&&!S.overlay)setOverlay('pause');});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(S.page==='game')setOverlay(S.overlay===null?'pause':null);else if(S.page==='phases')home();return;}if(S.overlay&&e.key==='Tab'){const controls=[...document.querySelectorAll('[role="dialog"] button')];if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function tick(t){const dt=Math.min(t-lastTick,70);lastTick=t;if(S.page==='game'&&!S.overlay){if(S.hold){S.hold.elapsed+=dt;document.querySelector('.dwell-ring')?.style.setProperty('--progress',`${Math.min(360,S.hold.elapsed/1200*360)}deg`);if(S.hold.elapsed>=1200)respond();}if(S.reward){S.reward=Math.max(0,S.reward-dt);if(S.reward===0){if(S.round>=3)S.overlay='done';else S.targetSlot=S.phase===1?0:S.round%(S.phase===2?2:3);render();}}if(S.toastRemaining){S.toastRemaining=Math.max(0,S.toastRemaining-dt);if(!S.toastRemaining){S.toast='';const n=document.querySelector('.toast');if(n)n.textContent='';}}}requestAnimationFrame(tick);}
render();requestAnimationFrame(tick);
